class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self.options: list[str] = []
        self.votes: dict[str, str] = {}  # voter -> option

    def add_option(self, option: str) -> None:
        if option not in self.options:
            self.options.append(option)

    def vote(self, voter: str, option: str) -> None:
        if option not in self.options:
            raise ValueError(f"Option '{option}' does not exist.")
        if voter in self.votes:
            raise ValueError(f"Voter '{voter}' has already voted.")
        self.votes[voter] = option

    def winner(self) -> str | None:
        if len(self.votes) < 3:
            return None
        counts: dict[str, int] = {opt: 0 for opt in self.options}
        for opt in self.votes.values():
            counts[opt] += 1
        # Tie-break: option added last wins, so iterate in reverse addition order
        best: str | None = None
        best_count = -1
        for opt in reversed(self.options):
            if counts[opt] > best_count:
                best = opt
                best_count = counts[opt]
        return best
